-- World Essentials reviewed overlay; upstream certificate: tools/community-kbw-sources.json
if not getActivatedMods():contains("KnoxCommunityTilepack") then return end
-- AUTO-GENERATED by pz_craft_loops/kbw_tilepatch.py -- do not edit by hand.
-- Right-click a Future Room viewscreen to cycle its image: frosted -> Earth -> Mars -> frosted.
-- Swaps the placed object's sprite (same pattern as vanilla ISWallpaperAction), so the choice is
-- saved with the object and synced to clients. No light source is involved.
require "TimedActions/ISBaseTimedAction"
local policy = require "Patches/WorldEssentialsGuestActions"

local NEXT = {
    ["DylansFutureRoom01_24"] = { "DylansFutureRoom01_27", "mars" },
    ["DylansFutureRoom01_25"] = { "DylansFutureRoom01_28", "mars" },
    ["DylansFutureRoom01_26"] = { "DylansFutureRoom01_29", "mars" },
    ["DylansFutureRoom01_27"] = { "DylansFutureRoom01_32", "frosted" },
    ["DylansFutureRoom01_28"] = { "DylansFutureRoom01_33", "frosted" },
    ["DylansFutureRoom01_29"] = { "DylansFutureRoom01_34", "frosted" },
    ["DylansFutureRoom01_32"] = { "DylansFutureRoom01_24", "earth" },
    ["DylansFutureRoom01_33"] = { "DylansFutureRoom01_25", "earth" },
    ["DylansFutureRoom01_34"] = { "DylansFutureRoom01_26", "earth" },
    ["KBWCommunityViewscreensN_0"] = { "KBWCommunityViewscreensN_3", "mars" },
    ["KBWCommunityViewscreensN_1"] = { "KBWCommunityViewscreensN_4", "mars" },
    ["KBWCommunityViewscreensN_2"] = { "KBWCommunityViewscreensN_5", "mars" },
    ["KBWCommunityViewscreensN_3"] = { "KBWCommunityViewscreensN_6", "frosted" },
    ["KBWCommunityViewscreensN_4"] = { "KBWCommunityViewscreensN_7", "frosted" },
    ["KBWCommunityViewscreensN_5"] = { "KBWCommunityViewscreensN_8", "frosted" },
    ["KBWCommunityViewscreensN_6"] = { "KBWCommunityViewscreensN_0", "earth" },
    ["KBWCommunityViewscreensN_7"] = { "KBWCommunityViewscreensN_1", "earth" },
    ["KBWCommunityViewscreensN_8"] = { "KBWCommunityViewscreensN_2", "earth" },
}
-- New isolated sprites share behavior while old placed objects retain legacy support.
local privateSprites = require "WorldEssentialsCommunitySprites"
local privateEntries = {}
for name, entry in pairs(NEXT) do
    local privateName = privateSprites[name]
    if privateName then
        privateEntries[privateName] = { privateSprites[entry[1]] or entry[1], entry[2] }
    end
end
for name, entry in pairs(privateEntries) do NEXT[name] = entry end

local LABEL = { frosted = "Viewscreen: Frost the Glass", earth = "Viewscreen: Show Earth", mars = "Viewscreen: Show Mars" }

KBWCycleViewscreenAction = ISBaseTimedAction:derive("KBWCycleViewscreenAction")

function KBWCycleViewscreenAction:isValid()
    local o, p = self.object, self.character
    if not o or not p or o:getObjectIndex() == -1 then return false end
    local sq, spr = o:getSquare(), o:getSprite()
    if not sq or not spr or not NEXT[spr:getName()] then return false end
    if math.floor(p:getZ()) ~= sq:getZ() or math.abs(p:getX()-sq:getX()) > 2
        or math.abs(p:getY()-sq:getY()) > 2 then return false end
    return policy.objectAllowed(o,p)
end

function KBWCycleViewscreenAction:waitToStart()
    self.character:faceThisObject(self.object)
    return self.character:shouldBeTurning()
end

function KBWCycleViewscreenAction:update()
    self.character:faceThisObject(self.object)
end

function KBWCycleViewscreenAction:start()
    self:setActionAnim("Loot")
end

function KBWCycleViewscreenAction:perform()
    ISBaseTimedAction.perform(self)
end

function KBWCycleViewscreenAction:complete()
    if not self:isValid() then return false end
    local spr = self.object and self.object:getSprite()
    local entry = spr and NEXT[spr:getName()]
    if entry then
        self.object:setSpriteFromName(entry[1])
        self.object:transmitUpdatedSpriteToClients()
    end
    return true
end

function KBWCycleViewscreenAction:getDuration()
    return 20
end

function KBWCycleViewscreenAction:new(character, object)
    local o = ISBaseTimedAction.new(self, character)
    o.object = object
    o.maxTime = o:getDuration()
    o.stopOnWalk = true
    o.stopOnRun = true
    return o
end

local function onCycle(playerObj, object)
    if luautils.walkAdj(playerObj, object:getSquare(), true) then
        ISTimedActionQueue.add(KBWCycleViewscreenAction:new(playerObj, object))
    end
end

local function addMenu(player, context, worldobjects, test)
    if test then return end
    local playerObj = getSpecificPlayer(player)
    if not playerObj then return end
    local seen = {}
    local squares = {}
    for _, wo in ipairs(worldobjects) do
        local sq = wo and wo.getSquare and wo:getSquare()
        if sq and not squares[sq] then
            squares[sq] = true
            local objs = sq:getObjects()
            for i = 0, objs:size() - 1 do
                local o = objs:get(i)
                local spr = o and o:getSprite()
                local entry = spr and NEXT[spr:getName()]
                if entry and not seen[o] and policy.objectAllowed(o,playerObj) then
                    seen[o] = true
                    context:addOption(LABEL[entry[2]] or "Viewscreen: Change Image", playerObj, onCycle, o)
                end
            end
        end
    end
end

if Events.OnFillWorldObjectContextMenu then
    Events.OnFillWorldObjectContextMenu.Add(addMenu)
end

require("WorldEssentialsPatchHealth").set("Community viewscreen permissions","OK","Live target, range and guest permission validation at completion; deduplicated menu squares")
